using System.Text.Json.Nodes;
using AuthLens.Domain.Json;
using AuthLens.Domain.Sod;

namespace AuthLens.Tests;

/// <summary>Golden comparison with Python v1 sod_reference.parse. Fixtures/sod/reference/*.xlsx.bin and expected.python.json are generated by
/// tools/sod_reference_fixtures.py from synthetic workbooks (valid inline, shared and rich-text strings, Definitions, column order, and every
/// refusal path).</summary>
public sealed class SodReferenceWorkbookTests
{
    private static readonly string Folder = Path.Combine(AppContext.BaseDirectory, "Fixtures", "sod", "reference");
    private static readonly JsonObject Expected = JsonNode.Parse(File.ReadAllText(Path.Combine(Folder, "expected.python.json")))!.AsObject();

    public static IEnumerable<object[]> Cases() => Expected.Select(p => new object[] { p.Key });

    private static object? Plain(JsonNode? node) => node switch
    {
        JsonObject o => o.ToDictionary(p => p.Key, p => Plain(p.Value)),
        JsonArray a => a.Select(Plain).ToList(),
        JsonValue v when v.TryGetValue<string>(out var s) => s,
        JsonValue v when v.TryGetValue<bool>(out var b) => b,
        JsonValue v when v.TryGetValue<long>(out var l) => l,
        _ => null,
    };

    [Theory]
    [MemberData(nameof(Cases))]
    public void Parse_matches_python_v1(string name)
    {
        var raw = File.ReadAllBytes(Path.Combine(Folder, name + ".xlsx.bin"));
        var expected = Expected[name]!;
        if ((bool)expected["ok"]!)
        {
            var library = SodReferenceWorkbook.Parse(raw);
            var python = expected["library"]!;
            Assert.Equal((string)python["digest"]!, library.Digest);
            Assert.Equal(CanonicalJson.Serialize(Plain(python["risks"])), CanonicalJson.Serialize(library.Risks.ToDictionary(p => p.Key, p => (object?)p.Value.ToDictionary(v => v.Key, v => (object?)v.Value))));
            Assert.Equal(CanonicalJson.Serialize(Plain(python["activities"])), CanonicalJson.Serialize(library.Activities.ToDictionary(p => p.Key, p => (object?)p.Value.ToDictionary(v => v.Key, v => (object?)v.Value))));
            Assert.Equal(CanonicalJson.Serialize(Plain(python["terms"])), CanonicalJson.Serialize(library.Terms.ToDictionary(p => p.Key, p => (object?)p.Value)));
            return;
        }
        var error = Assert.Throws<ReferenceWorkbookException>(() => SodReferenceWorkbook.Parse(raw));
        // v1 reports field-model failures with Pydantic's own text; both refuse the same workbook, and every other message is identical.
        if ((bool)expected["pydantic"]!) Assert.True(error.FieldValidation, error.Message);
        else Assert.Equal((string)expected["error"]!, error.Message);
    }
}
